INSERT INTO `Project` (`project_id`, `project_name`, `project_simple_name`, `project_description_short`, `project_description_short_fr`, `project_description`, `project_description_fr`, `project_start_year`, `project_end_year`, `category_id`, `project_featured`, `project_visible`) VALUES
(2, 'SkinSwitch', 'skinswitch', 'Complete skin manager for Minecraft.', 'Gestionnaire de skins pour Minecraft.', 'SkinSwitch is the most simple skin manager for Minecraft ever designed.\n\n1.  Enter your minecraft.net login/password in the app (don\'t worry, they\'re stored safely and will never be used for anything else than changing your skin);\n2.  Add as many skins as you want in the application, by getting them from the username of another player that is already wearing it, or by downloading them from their URL;\n3.  The list of all your skins is displayed on the main page; you only have to tap **one** button to instantly wear the Minecraft skin you just chose.\n\nYou can integrate SkinSwitch with your own website or application by using its URL scheme: for example, click on this link to [add Notch\'s skin to the app](skinswitch://?name=The%20Creator&desc=Notch,%20or%20Markus%20Persson,%20created%20Minecraft%20in%202009.&url=https://s3.amazonaws.com/MinecraftSkins/Notch.png).\n\nA [web version of SkinSwitch](http://skinmanager.fr.nf) was also created by [EphysPotato](http://twitter.com/EphysPotato), and is used to browse skins inside the app!', 'SkinSwitch est un moyen pratique pour gérer vos skins Minecraft directement depuis votre smartphone ou tablette. L\'app vous permet d\'ajouter rapidement vos skins Minecraft préférés depuis une gallerie en ligne, le skin d\'un autre joueur, ou directement depuis n\'importe où sur le web. Vous pouvez alors vous connecter à votre compte Minecraft/Mojang et changer de skin en quelques secondes !\n\nLa version Android repose sur une interface Material élégante et simple à utiliser, et devrait être compatible avec tous les appareils sous Android 4.0 et plus.\n\nSkinSwitch inclut également une app Android Wear depuis laquelle vous pouvez changer vos skins encore plus facilement, avec votre voix. Dites simplement \"Ok Google, lancer SkinSwitch\", et dites le nom du skin que vous voulez porter !\n\nL\'app ne fonctionne qu\'avec la version PC de Minecraft, et n\'est pas compatible avec la version Xbox 360, ni la Pocket Edition. Vous devez avoir également acheté le jeu complet, nous ne pouvons pas supporter les versions piratées de Minecraft.\n\nVous pouvez intégrer SkinSwitch à d\'autres applications ou sites web en utilisant le schéma d\'URI dédié. Par exemple, cliquez sur ce lien pour [ajouter le skin de Notch à l\'application](skinswitch://?name=The%20Creator&desc=Notch,%20or%20Markus%20Persson,%20created%20Minecraft%20in%202009.&url=https://s3.amazonaws.com/MinecraftSkins/Notch.png).', 2012, 2015, 1, 0, 1),
(4, 'FreeStance', 'freestance', 'Remote control your Freebox.', 'Contrôlez votre Freebox à distance.', 'FreeStance is an iOS application that is designed to control your Freebox, a set-top box distributed by the French ISP _Free_, remotely.\n\nFreeStance was my first iOS application, and I wanted it to be full of features in a nice interface so that it brings something more than the existing remotes. It was developped using Appcelerator Titanium.\n\nFreeStance allows you to:\n\n*   Control up to 3 different Freebox\n*   Browse through the hundreds of available channels thanks to a simplified grid\n*   Browse the TV guide and get info about what you\'re watching\n*   Share the TV programs you like via Twitter, Facebook...', 'Marre de ne jamais retrouver cette encombrante télécommande ? Marre de devoir utiliser différentes télécommandes pour la Freebox de votre salon et celle de votre chambre ?\n\nVos souffrances s\'achèvent ! Grâce à FreeStance pour iOS, vous pourrez contrôler toutes vos Freebox dans une application native parfaitement dessinée.\n\nGrâce aux fonctionnalités innovantes de FreeStance, vous pourrez...\n\n*   Contrôler jusqu\'à trois Freebox différentes, et passer de l\'une à l\'autre en un seul toucher;\n*   Accéder à toutes les chaînes gratuites du bouquet Freebox sans aucun souci grâce à une grille, sans avoir à parcourir la liste des chaînes sur votre télévision;\n*   Consulter le programme TV, pour savoir quoi regarder en un coup d\'oeil;\n*   Partager les programmes intéressants avec le reste du monde, grâce à l\'intégration de Twitter dans iOS 5.\n\nVu sur : [UniversFreebox](http://www.universfreebox.com/article17413.html), [MacGeneration](http://www.igeneration.fr/concours/concours-15-licences-de-freestance-gagner-91742), [FreeiPhone](http://www.freeiphone.fr/freestance-nouvelle-application-de-telecommande-pour-freebox/)...', 2012, 2014, 1, 0, 1),
(5, 'Borguerie Center', 'borguerie-center', 'Website that lists Jérôme Keinborg\'s \"best\" puns.', 'Site regroupant les \"borgueries\" de Jérôme Keinborg.', 'This website was created to list all of Jérôme Keinborg\'s \"borgueries\", which are puns he used to make periodically on AppLoad, a podcast then produced by the NoWatch.net network.\n\nNothing serious intended, and you\'ll definitely need to understand French pretty well to enjoy it; if you do though, you should also check out the podcast on [Frenchspin.fr](http://frenchspin.fr). Still as fun!', 'Ce site regroupe les \"borgueries\" de Jérôme Keinborg, qui sont le surnom donné aux jeux de mots qu\'il préparait chaque semaine dans le podcast AppLoad, alors produit par NoWatch.net. Vous pouvez aujourd\'hui le retrouver sur [Frenchspin.fr](http://frenchspin.fr).\n\nRien de bien sérieux donc, mais si vous écoutez l\'émission ou êtes de nature blagueuse, vous passerez un bon moment sur ce site !\n\nLe Borguerie Center a déjà été cité plusieurs fois dans AppLoad, merci aux animateurs !', 2012, 2012, 3, 0, 1),
(6, 'CallMeBack', 'cmb', 'Web-app for iOS that creates shortcuts to your contacts.', 'Application web iOS permettant de créer des raccourcis vers des contacts.', 'This web-app, compatible with iOS only (iPhone, iPad and iPod Touch), allows you to create shortcuts to your contacts on your home screen, and all of this without to jailbreak your device.\n\nYou\'ll only have to specify if you want to create a shortcut to a Facetime contact or a phone number, as well as the said number and the name of your contact, without forgetting the color of the created icon. You\'ll only have to tap this icon the next time you want to call or Facetime this contact!', 'Cette application web vous permet de créer des raccourcis vers vos contacts sur votre appareil iOS, sans avoir à le jailbreaker.\r\n\r\nIl vous suffit de préciser si vous souhaitez créer un raccourci Facetime ou téléphone, ajouter le numéro et le nom du contact, sans oublier la couleur de l\'icône. Vous n\'aurez plus qu\'à taper sur cette dernière pour passer un appel !', 2011, 2012, 1, 0, 1),
(7, 'FantaBobMod', 'fantabobmod', 'Mod for Minecraft featuring TheFantasion974 and Boblennon.', 'Mod Minecraft avec Fanta et Bob.', 'My first [Minecraft](http://minecraft.net) mod, which adds mobs and items based on TheFantasio974 and Bob Lennon, two French Minecraft youtubers.', 'Mon premier mod pour [Minecraft](http://minecraft.net), créé pour le fun et avec pour thème les fameux TheFantasio974 et Bob Lennon. Ils tiennent [des chaînes Youtube](http://www.youtube.com/user/TheFantasio974) et sont principalement connus pour leurs vidéos sur Minecraft. Le mod ajoute au jeu des mobs à leur image (et à leur voix, aussi !), des items ainsi que des blocs en référence à certaines de leurs émissions.', 2011, 2013, 5, 0, 1),
(8, 'FreeStance Desktop', 'freestance-desktop', 'Remote control your Freebox from your computer.', 'Contrôlez votre Freebox depuis votre ordinateur.', 'The desktop version of FreeStance was one of my first desktop programs. This application allows you to control your Freebox (French set-top box) from your computer.\r\n\r\nFreeStance desktop is still compatible with Windows, OS X and Linux.', 'Ce programme, développé avec le framework Qt, est la version bureau de FreeStance pour iOS et pour Chrome. Malgré qu\'il ne soit actuellement plus développé, il n\'en reste pas moins pleinement fonctionnel et ravira les freenautes n\'utilisant pas de [smartphone sous iOS](../freestance/) ou le [navigateur Google Chrome™](../freestance-chrome/). \r\n\r\nFreeStance Desktop est compatible Windows, OS X et Linux.', 2009, 2011, 2, 0, 1),
(9, 'FreeStance Chrome', 'freestance-chrome', 'Remote control your Freebox from your browser.', 'Contrôlez votre Freebox depuis votre navigateur.', 'FreeStance for Google Chrome is the web browser version of FreeStance, designed to remote control your Freebox (French set-top box) right from your Internet-browsing device.\r\n\r\nThe main features of this remote is that it\'s simple and easy to use, and fits right next to your address bar so it\'s neither a pain to find nor too intrusive.\r\n\r\nYou can also check out FreeStance for [iOS](./freestance) and [desktop](./freestance-desktop).', 'Vous avez aimé FreeStance pour iOS, mais vous en voulez plus ? Ou au contraire, vous n\'avez pas d\'appareil compatible avec FreeStance pour iOS, et vous souhaiteriez profiter de quelques unes de ses fonctionnalités ?\n\nVous avez besoin de FreeStance pour Google Chrome™ ! Cette extension pour le navigateur permettra aux accros du net de contrôler leur Freebox en deux clics, littéralement.\n\nSe logeant dans votre barre d\'outils, FreeStance saura se faire discret jusqu\'à ce que vous ayez besoin de lui. Vous n\'aurez qu\'à le paramétrer après l\'installation : supportant, comme la version iOS, trois profils pour contrôler trois Freebox différentes, vous n\'aurez même pas besoin de tout reconfigurer pour changer de Freebox cible, comme avec d\'autres solutions qui se veulent équivalentes.', 2010, 2013, 4, 0, 1),
(10, 'TabQuote', 'tabquote', 'A new quote on your new tab page, every day.', 'Chaque jour, une nouvelle citation sur votre page \"nouvel onglet\".', 'This Google Chrome extension replaces your - often useless - new tab page with a simple and clear one that shows a new quote every day.\r\n\r\nYou can still access your installed applications from within the new tab page; after a short delay, a button will appear in the bottom-right of the page. Click it and you\'ll be able to access all your apps!', 'Cette extension pour Google Chrome remplace votre page \"nouvel onglet\" par une citation aléatoire, qui change chaque jour.\r\n\r\nVous pouvez toujours accéder à vos applications Chrome si vous aviez l\'habitude de passer par cette page pour les trouver : après un court délai, un bouton \"Apps\" va apparaître dans le coin en bas à droite. Cliquez dessus pour y accéder !', 2012, 2012, 4, 0, 1),
(11, 'Youtube Videos Hider', 'yt-videos-hider', 'Hide the series you don\'t like from your YouTube homepage.', 'Faites disparaître les séries que vous n\'aimez pas de vos abonnements YouTube.', 'Are you tired of being subscribed to people that make series you\'re not interested in? But you don\'t want to unsubscribe them, because you like some of their videos nevertheless? YT Videos Hider is for you!\n\nThis extension allows you to hide certains videos from your Youtube home page based on their title. Just follow the instructions on the options page, save your filters and you\'re done.', 'Fatigué de voir apparaître dans vos abonnements YouTube des séries qui ne vous intéressent pas ? Problème... vous ne voulez pas vous désabonner, ce qui signifierait dire au-revoir aux autres séries de ces youtubers qui elles vous intéressent.\r\n\r\nCette extension vous permet de cacher certaines vidéos YouTube de votre flux d\'abonnement. Seules les vidéos ne contenant pas une certaine chaîne de caractères que vous spécifiez seront affichées, ce qui vous permet de filtrer ce qui ne vous intéresse pas !', 2012, 2013, 4, 0, 1),
(12, 'InverseLook', 'inverselook', 'Invert the columns of the #NewNewTwitter.', 'Inversez les colonnes du #NewNewTwitter.', 'This Google Chrome extension is for the nostalgics. In the good old days, Twitter used to have its columns the other way; the timeline on the left, and the rest on the right. This brings back the right order of things, even thought I would still recommend you use a third-party Twitter client instead.', 'Cette extension Google Chrome inverse les colonnes du site officiel de Twitter, mimiquant l\'ancien aspect du réseau social.', 2011, 2013, 4, 0, 1),
(13, 'DansTonChat Note', 'dtc-note', 'Show the scores on DansTonChat\'s quotes.', 'Affichez de nouveau les notes sur les quotes de DansTonChat.', 'This Google Chrome extension displays the scores on DansTonChat\'s quotes (bash.org equivalent), after they were removed in an earlier version.\r\n\r\nThe algorithm and JS script were written by Baptiste \"ashka\" Huve. I only made the Google Chrome port.', 'Cette extension Google Chrome permet d\'afficher à nouveau la note sur les quotes de [DansTonChat.com](https://danstonchat.com), disparues depuis la \"nouvelle\" version.\r\n\r\nL\'algorithme et le script ont été écrits par Baptiste \"ashka\" Huve, je n\'ai fait que le portage sur Chrome.', 2011, 2013, 4, 0, 1),
(14, 'CAPS LOCK DAY', 'caps-lock-day', 'WHEN IT\'S CAPS LOCK DAY, YOU\'LL KNOW IT. REALLY.', 'QUAND LE CAPS LOCK DAY ARRIVERA, VOUS LE SAUREZ. VRAIMENT.', 'ON EVERY INTERNATIONAL CAPS LOCK DAY, THIS EXTENSION WILL MAKE YOU UNABLE TO TYPE IN LOWER CASE, AND WILL DISPLAY EVERY WEB PAGE (OR ALMOST) AS IF IT WAS IN UPPER CASE.\n\nFOR YOUR INFORMATION, CAPS LOCK DAY IS ON OCTOBER 22 AND JUNE 28 OF EVERY YEAR. BUT WITH THIS EXTENSION YOU WON\'T HAVE TO REMEMBER IT ANYMORE. REALLY.', 'DURANT CHAQUE JOUR INTERNATIONAL DU VERR. MAJ, OU CAPS LOCK DAY, CETTE EXTENSION VOUS FORCERA DANS LE MEILLEUR MODE D\'ÉCRITURE JAMAIS INVENTÉ : LES MAJUSCULES.\r\n\r\nOH, AUSSI, TOUT LE WEB S\'AFFICHERA EN MAJUSCULES.\r\n\r\nCHAQUE 22 OCTOBRE ET 28 JUIN.\r\n\r\nYUP.', 2012, 2012, 4, 0, 1),
(15, 'La Trouvaille', 'la-trouvaille', 'Professional project for an ancient gas pumps seller.', 'Projet professionnel de vente de pompes anciennes.', 'My first commissioned project, where I had to rewrite from scratch the website of a french seller of petrol pumps.', 'Mon premier projet pour un client, La Trouvaille, consistant en un site web vitrine en PHP qui propose leur catalogue de pompes anciennes.', 2012, 2012, 3, 0, 1),
(16, '#CuteFF', 'cuteff', 'A simple webpage to show my #FollowFriday\'s.', 'Une simple page web pour publier mes #FollowFriday.', 'Not much of a website; a web page I sometimes use when I want my #FollowFriday\'s look original on Twitter. It had several design changes, and you can find the code on its [Github repository](https://github.com/outadoc/CuteFF).', 'Une petite page web que j\'ai utilisé pendant un moment pour diffuser mes #FollowFriday sur Twitter. Présentée avec un fond sympa, un peu de musique et quelques animations, elle est plutôt conviviale !', 2012, 2013, 3, 0, 1),
(17, 'Twitter Archive Parser', 'twitter-archive-parser', 'Store all of your tweets in a single database.', 'Stockez tous vos tweets dans une base de données unifiée.', 'Before Twitter introduced its archiving system, there was no way to download all your personal information from their servers and save it on your computer.  \r\n\r\nThere was a workaround, though; but you had to live in the **European Union** to request it.  \r\nIf it was your case, you had to follow [these instructions](https://www.privacyinternational.org/blog/what-does-twitter-know-about-its-users-nologs), and wait a few days for Twitter to send you your tweets in an archive.  \r\n\r\nThen, only had to clone this project on your server or computer, and follow the instructions on the Github repo to get a nice SQLite database containing your tweets!\r\n\r\nThis script will **not** work with the newer archives provided by Twitter *via* their website.', 'Avant que Twitter ne propose le téléchargement individuel des données personnelles de ses utilisateurs, il n\'existait pas de moyen direct d\'obtenir une archive contenant ses tweets.\r\n\r\nSi vous étiez citoyen de l\'Union Européenne cependant, il était possible de demander une telle archive à Twitter; seulement, celle-ci étant difficile à exploiter, j\'ai créé un outil permettant d\'analyser l\'archive et insérer les tweets dans une base de données SQLite.\r\n\r\nL\'outil est disponible sur Github, mais ne fonctionnera pas avec les archives distribuées dernièrement par Twitter *via* leur site web.', 2012, 2012, 5, 0, 1),
(18, 'Server List', 'server-list', 'Your favorite Minecraft servers, anywhere.', 'Vos serveurs Minecraft préférés, n\'importe où.', 'Server List for Minecraft is the best way to simply manage and control your favorite Minecraft servers.\n\nEither if you are a player or a server administrator that wants to control the status of his server, Server List will seduce you by its simplicity of usage and its lightness.\n\nEverything is done as in the original Minecraft list, except you can just keep your device with the list displayed while you\'re already playing, you don\'t have to open the game just to check if there are free slots on your favorite server...\n\nJust click \'add\', enter the information about the server, click \'done\', and that\'s it! Your server is added to the main screen.', 'Server List pour Minecraft est une application iOS vous permettant de toujours garder un oeil sur votre liste de serveurs Minecraft favoris.\r\n\r\nLe fonctionnement est similaire à celui de la liste de serveurs dans Minecraft lui-même : vous pouvez ajouter un serveur à la liste, ce qui récupérera automatiquement le MOTD, le nombre de joueurs, et le nombre total de slots sur le serveur.', 2012, 2013, 1, 0, 1),
(19, 'Play2Twitter', 'play2twitter', 'Share the music you\'re listening to on Twitter.', 'Partagez sur Twitter la musique que vous écoutez.', 'Ever wanted to share the music you\'re listening to on Google Play Music with your Twitter followers? \r\n\r\nThis extension will add a button to your omnibox when you\'re listening to a song; just click it, and a window with a #NowPlaying tweet ready to sent will appear. Click, and spread the word!', 'Si vous aimez écouter votre musique avec Google Play Musique, Play2Twitter est pour vous.\r\n\r\nCette extension ajoute un bouton dans la barre d\'adresse vous permettant de partager la musique en cours de lecture sur Twitter, en utilisant le hashtag #NowPlaying.\r\n\r\nC\'est à votre tour de partager votre musique avec le monde entier !', 2012, 2013, 4, 0, 1),
(20, 'outa[bot] for Twitter', 'outabot-twitter', '\"Intelligent\" customizable bot for Twitter.', 'Robot \"intelligent\" et personnalisable pour Twitter.', 'Just a Twitter bot that listens for what you\'re saying. It will retweet every tweet mentionning him, and reply something random using [Yes That Can Be My Next Tweet](http://yes.thatcan.be/my/next/tweet). It\'s designed to imitate a targeted user to make a parody account, for example.  \r\n\r\nFollow the intructions on Github to configure it.', 'Ce bot Twitter écoute ce que vous lui dites et répond aléatoirement... en utilisant les anciens tweets de la personne que vous spécifiez.\r\n\r\nLe bot est conçu pour créer des comptes Twitter parodiques qui répondent en \"faisant croire\" que la personne ciblée est celle qui a tapé le tweet. Forcément, l\'algorithme est peu convaincant mais peut donner des résultats extrêmement drôles.\r\n\r\nSuivez les instructions sur Github pour le configurer.', 2013, 2013, 5, 0, 1),
(21, 'Rand0matic for Twitter', 'randomatic-twitter', 'Twitter bot that replies random things. Based on you.', 'Robot pour Twitter qui répond aléatoirement. En se basant sur vos tweets.', 'Just a Twitter bot that listens for what you\'re saying. It will answer every tweet mentionning it something random it got from the previous tweets of the mentionner.\r\n\r\nBegin by opening a new account for the bot on Twitter. Then, create an application for this account on dev.twitter.com, and get the API keys. Setup in apiKeys.json.\r\n\r\nMore info is available on Github.', 'Ce bot Twitter répond à ses mentions avec des phrases aléatoire construites à partir des tweets précédents de la personne qui l\'a mentionné. Plus simplement : envoyez-lui un message, vous aurez une conversation avec vous-même !\r\n\r\nRand0matic est basé sur outa[bot], avec un comportement différent. Le code est normalement un peu plus stable, mais très loin d\'être parfait.\r\n\r\nLes instructions de configuration sont sur Github.', 2013, 2013, 5, 0, 1),
(22, 'Twisto API', 'twisto-api', 'API allowing you to get the schedules of the Twisto bus network in real time.', 'API permettant de récupérer les horaires du réseau Twisto en temps réel.', '**This API is now deprecated. Prefer using the [official API](https://gist.github.com/outadoc/40060db45c436977a912).**\r\n\r\nThis API provides real time info for the buses and trams of the Twisto network (operating in Caen, France) as JSON data.\r\n\r\nIt allows the user to retrieve lists of bus lines, directions and stops, and can then be used to fetch real time bus info for every stop.\r\n\r\nMore info on Github.', '**Cette API est maintenant dépréciée. Utilisez plutôt [l\'API officielle](https://gist.github.com/outadoc/40060db45c436977a912).**\r\n\r\nCe projet consiste en une API écrite en PHP qui vous permet de récupérer les horaires des bus et trams du réseau Twisto en temps réel.\r\n\r\nLes données sont retournées en JSON pour une facilité d\'utilisation accrue, et le script peut tourner sur n\'importe quel serveur web supportant PHP et curl.\r\n\r\nPlus d\'informations sur Github.', 2013, 2014, 5, 0, 1),
(23, 'Twistoast', 'twistoast', 'Stay informed of the schedule of the Twisto bus network in real time.', 'Restez informé en temps réel des horaires sur le réseau Twisto.', 'Twistoast is an application that will guide you through the network of buses and tramways of Caen, Normandy (France). Twistoast will help you find the right bus in Caen, as it is an alternative to the web-based official app. It\'s been mostly translated in English, to help you whether you are a tourist visiting the city or an English-speaker living in Caen.\n\nMain features:\n\n*   A native list of bus stops that you can personalize, to always have access to all the information you need at the time you need it;\n*   Notifications and a Pebble application, so you can have all the next schedules at a glance;\n*   An auto-refresh feature, to make sure you always have the freshest data;\n*   Access to all of the bus schedules, so that you can plan your trips in advance;\n*   And all the useful features you may need, such as routes calculation, trafic info, and news about the network.\n\nTwistoast is free and available for all phones and tablets running Android 4.0+.\n\nEnjoy the ride!', 'Twistoast est une application destinée aux utilisateurs de Twisto, réseau bus et trams de Caen (France).\n\nL\'application améliore grandement le service officiel de Twisto en ce qui concerne la consultation des prochains passages des bus en temps réel. Vous pouvez ainsi ajouter un nombre virtuellement illimité d\'arrêts de bus dans l\'application, et ils seront tous conservés, là où l\'application officielle ne peut en contenir qu\'un nombre très limité.\n\nEn plus de cela, Twistoast vous propose les mêmes fonctionnalités que l\'application officielle : horaires en temps réel, itinéraires, info trafic, tarifs...\n\nUne application Pebble est également disponible afin de vous permettre de consulter facilement et rapidement les horaires de votre bus depuis votre montre. Téléchargez et activez-la depuis les paramètres de Twistoast !\n\nTwistoast est disponible sur les appareils post-ICS et propose une interface Material Design agréable à utiliser.', 2013, NULL, 1, 1, 1),
(24, 'DeLorean Speedometer', 'obd-speedometer', 'OBD-II enabled Back to the Future-style speedometer for Android.', 'Compteur de vitesse OBD-II dans le style de Retour vers le Futur.', 'Are you a fan of the Back to the Future movies? So am I! This application is a plugin for Torque, an application that connects to your car via an OBD-II adapter. You need it to use this app!\r\n\r\nOBD DeLorean Speedometer does what it says: it\'s a Back to the Future-styled DeLorean speedometer (the digital one Doc built) that connects to your car and displays its speed in real time. With optional time travel sound effects!\r\n\r\n**Warning:** this is not an ACCURATE speedometer and should not be used as such, despite usually not being too far from the actual speed. Keep an eye on your genuine car speedometer. Seriously.', 'Si vous êtes fan de Retour vers le Futur et propriétaire d\'une voiture avec un port de diagnostique OBD-II, vous voudrez probablement essayer cette app !\r\n\r\nAprès avoir connecté un adaptateur OBD-II dans votre voiture, téléchargé Torque et installé cette app, vous aurez à votre disposition un compteur de vitesse numérique fidèle à celui aperçu dans le film.\r\n\r\nL\'application propose même des effets sonores ainsi qu\'un mode voyage dans le temps lorsque vous atteignez 88 miles ou kilomètres par heure ! (pensez à configurer l\'unité dans les préférences)\r\n\r\n**Attention :** ce compteur n\'est PAS un compteur de vitesse précis, et n\'est certainement pas censé l\'être, malgré une précision qui ne devrait pas trop s\'éloigner de la vitesse réelle. Gardez un oeil sur le compteur de votre voiture. Sérieusement.', 2014, 2014, 1, 0, 1),
(25, 'Scrobb', 'scrobb', 'A simple, lightweight Last.fm scrobbler.', 'Un scrobbler Last.fm simple et léger.', 'There are quite a few Last.fm scrobblers out there, but this one is different. \r\n\r\nScrobb is based on the sources of the official Last.fm application. We only kept the bare minimum: the scrobbler. A few bugs which caused crashes were fixed, and the UI was updated for today\'s devices. \r\n\r\nWhich means that when the official app is able to scrobble something, Scrobb should be able to scrobble it too! It\'s more lightweight and more stable. \r\n\r\nI also plan on adding a couple extra features in the future if I find out how. Please keep in mind that Scrobb is in no way associated with Last.fm, and you should still check out their official app if you want the complete experience!', 'Il existe déjà des scrobblers pour Last.fm dans la nature, mais celui-ci est différent.\r\n\r\nScrobb repose sur les sources de l\'application officielle Last.fm. Nous n\'avons gardé que l\'essentiel : le scrobbler. Quelques bugs ont même été corrigés, et l\'interface utilisateur a été mise à jour pour les appareils d\'aujourd\'hui.\r\n\r\nÇa veut dire que si l\'application officielle peut scrobbler quelque-chose, Scrobb peut le faire aussi ! En plus, Scrobb est plus légère et stable.\r\n', 2015, NULL, 1, 0, 1),
(26, 'Splat Companion', 'splat-companion', 'Get the freshest Splatoon™ stage rotations right on your mobile device!', 'Visualisez facilement les stages actuellement en rotation sur Splatoon™ !', 'Splat Companion is a simple yet useful app that will inform you of the current Splatoon stages without having to boot up the game!\r\n\r\nThat\'s all, really. But it\'s really nice!\r\n\r\nStage names are localized in English, French, German, Spanish, Italian, and Japanese.\r\nThe data is fetched in real time thanks to splatoon.ink\'s API.', 'Splat Companion est une application toute simple qui vous informera des stages Splatoon actuellement en rotation, sans avoir à lancer le jeu.\r\n\r\nC\'est tout, en fait. Mais c\'est pratique !\r\n\r\nLes noms des stages sont localisés en anglais, français, allemand, espagnol, italien et japonais.\r\nLes données sont récupérées en temps réel via l\'API de splatoon.ink.', 2015, NULL, 1, 1, 1),
(27, 'Linkindle', 'linkindle', 'Display your energy consumption trends right from your Linky, onto a Kindle', 'Affichez le graphe de votre consommation énergétique directement depuis votre Linky, sur une Kindle', 'I wanted a way to display my energetic consumption on my wall, like on a weather station. I looked into different display solutions, and it turns out the nicest and easiest seems to be hacking a Kindle into displaying images refreshed periodically.\r\n\r\nI therefore started making a graph generator that would take the data reported by my Linky electricity meter. The data is sent periodically to Enedis, which in turn offers a webpage which displays it - and makes it available through a private JSON API.\r\n\r\nA few hours later, I had a Python script that could log into the Enedis website and download the meter\'s data. It can then be processed by the Python script, to generate PNG files of graphs that I will then display on the jailbroken Kindle.\r\n\r\nCheck the Github repository and [this blog post (fr)](https://outadoc.fr/2016/12/linkindle-courbe-conso-electrique-sur-liseuse/) for more info!', 'J\'avais envie d\'afficher mes graphes de consommation énergétique sur mon mur, comme avec une station météorologique. Après avoir évalué les solutions d\'affichage, j\'ai compris que l\'afficheur le plus adapté et peu consommateur serait une Kindle, que je rafraîchirai périodiquement afin d\'afficher les dernières données.\r\n\r\nJ\'ai ainsi commencé à concevoir un générateur de graphe qui récupérerait les données reportées par mon compteur Linky. Les données sont envoyées périodiquement à Enedis, qui fournit alors une page web pour les consulter - et les rend disponible à travers une API JSON privée.\r\n\r\nQuelques heures plus tard, j\'avais un script Python qui pouvait se connecter au site d\'Enedis et télécharger les données de mon compteur. Les données sont ensuite traitées par Python *via* `matplotlib`, pour générer des fichiers PNG de graphes affichables sur la Kindle, une fois jailbreakée.\r\n\r\nVisitez le repo Github ansi que [ce post de blog](https://outadoc.fr/2016/12/linkindle-courbe-conso-electrique-sur-liseuse/) pour plus d\'infos !', 2016, NULL, 5, 1, 1),
(28, 'DeLorean Digital Speedometer Replica', 'obd-speedometer-arduino', 'Functioning replica of the DeLorean\'s digital speedometer from Back to the Future.', 'Réplique fonctionnelle du compteur de vitesse numérique de la DeLorean de Retour vers le Futur.', 'This project consisted in the making of a functional replica of the speedometer seen in the cult science-fiction film Back to the Future.\r\n\r\nThe finished product relies on a Freematics OBD-II UART adapter, connected directly to the car\'s ECU *via* the standard OBD-II port.\r\n\r\nThe circuit is controlled by an Arduino Nano board, wired to a switch (for mph/OFF/kmh functionality), the adapter, and two 7-segment displays.', 'Ce projet a consisté en la conception d\'une réplique fonctionnelle du compteur de vitesse vu dans le film culte de science-fiction Retour vers le Futur.\r\n\r\nLe produit fini repose sur un adaptateur UART OBD-II Freematics, connecté directement à l\'ordinateur de bord de la voiture par le port OBD-II standard.\r\n\r\nLe circuit est contrôlé par un Arduino Nano, connecté à un interrupteur (pour le mph/OFF/kmh), l\'adaptateur, et deux afficheurs sept segments.', 2017, 2017, 6, 0, 1),
(29, 'Borne 2 Be', 'borne2be', 'A collaborative kiosk for your community.', 'Une borne collaborative pour votre communauté.', 'The Borne 2 Be project was born in the framework of Semaine Intensive 2018, organized by ENSICAEN, Normandie Aménagement, Caen la Mer Habitation and OuiShare.\r\n\r\nBorne 2 Be is a community-driven kiosk that allows the people of a neighborhood to exchange local ads, news, to consult an interactive map, or the bus schedule.\r\n\r\nThe users can authenticate to post content thanks to their smart bracelet or contactless badge. \r\n\r\nI mostly worked on the project\'s hardware: setting up a Raspberry Pi with Android Things, creating an Apache Cordova wrapper for the kiosk\'s website, communication with the fab lab in general, and mostly the setup, configuration and integration of an NFC reader for user authentication.', 'Le projet Borne 2 Be est né dans le cadre de la Semaine Intensive 2018, organisée par l\'ENSICAEN, Normandie Aménagement, Caen la Mer Habitation et OuiShare. Durant une semaine, notre équipe a tout donné pour développer une projet sur le thème de Normandie Aménagement : \"vers une ville sans smartphone\".\r\n\r\nBorne 2 Be est une borne communautaire qui permet aux habitants d\'un quartier d\'échanger petites annonces, nouvelles, de consulter un plan interactif, ou encore les horaires des prochains bus.\r\n\r\nLes utilisateurs peuvent s\'authentifier pour poster du contenu grâce à leur bracelet ou badge connecté.\r\n\r\nJ\'ai principalement travaillé sur le hardware du projet : préparation d\'un Raspberry Pi avec Android Things, création d\'un wrapper Apache Cordova pour le site web de la borne, communication avec le fab lab en général, et surtout mise en place et intégration d\'un lecteur NFC pour l\'authentification des utilisateurs.', 2018, 2018, 6, 0, 1);
